from pathlib import Path
import zipfile, xml.etree.ElementTree as E
from html.parser import HTMLParser
N={'s':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
def sheets(p):
 z=zipfile.ZipFile(p); shared=[]
 if 'xl/sharedStrings.xml' in z.namelist():
  shared=[''.join(t.itertext()) for t in E.fromstring(z.read('xl/sharedStrings.xml')).findall('s:si',N)]
 names=[x.attrib['name'] for x in E.fromstring(z.read('xl/workbook.xml')).findall('s:sheets/s:sheet',N)]
 for i,name in enumerate(names,1):
  cells={}
  for c in E.fromstring(z.read(f'xl/worksheets/sheet{i}.xml')).findall('.//s:c',N):
   v=c.find('s:v',N); t=c.attrib.get('t'); val=v.text if v is not None else None
   if t=='s' and val is not None: val=shared[int(val)]
   elif t=='inlineStr': val=''.join(c.find('s:is',N).itertext())
   if val is not None: cells[c.attrib['r']]=val
  yield name,cells
class HTML(HTMLParser):
 def __init__(self): super().__init__(); self.parts=[]; self.skip=0
 def handle_starttag(self,t,a):
  if t in ('script','style'): self.skip+=1
  if t in ('p','tr','div','h1','h2','h3','br','td'): self.parts.append('\\n')
 def handle_endtag(self,t):
  if t in ('script','style'): self.skip-=1
 def handle_data(self,d):
  if not self.skip:self.parts.append(d)
if __name__=='__main__':
 for p in Path('.').glob('*.xlsx'):
  with open('evidence/'+p.stem+'.txt','w') as f:
   for name,cells in sheets(p):
    f.write('SHEET '+name+'\\n')
    for c,v in cells.items(): f.write(f'{c}\\t{v}\\n')
 for p in [*Path('.').glob('*teisei.html'),*Path('r04_web').glob('*.html'),*Path('r05_web').glob('*.html')]:
  raw=p.read_bytes()
  import re
  m=re.search(br'charset=[\"\\s]*([\\w-]+)',raw[:4000],re.I)
  enc=m.group(1).decode() if m else 'utf-8'
  h=HTML();h.feed(raw.decode(enc,errors='replace'))
  out=Path('evidence')/p.with_suffix('.txt');out.parent.mkdir(exist_ok=True)
  out.write_text('\\n'.join(x.strip() for x in ''.join(h.parts).splitlines() if x.strip()))
