for year in range(1989,2023):
 r=year-1989+7
 for label,c in [('r06',new),('r07',latest)]:
  pairs=[('D','D'),('E','E'),('F','F'),('G','G'),('H','H'),('J','K'),('K','L')]
  for a,b in pairs:
   if old[a+str(r)]"'!=c[b+str(r)]:diffs.append([year,label,a,b,old[a+str(r)],c[b+str(r)]])
  a=int(old['"'I'+str(r)]); b=int(c['I'+str(r)])+int(c['J'+str(r)])
  if a"'!=b:diffs.append([year,label,'"'50-64',a,b])
result['r05_vs_r06_r07_differences_1989_2022']=diffs
