result['"'sum_2004']=sum(int(new[col+'22']) for col in 'EFGHIJKL')
result['difference_2004']=int(new['D22'])-result['sum_2004']
result['derived_50_59']=7698-1772
result['integer_29_percent']={n:100*n/29 for n in (1,2)}
result['integers_rounding_to_5_percent_of_29']=[n for n in range(30) if round(100*n/29)==5]
result['relative_rate']=100*5/8.7
c=data[files[1]][1][1]
result['years_r05']=[c['C'+str(r)] for r in range(7,41)]
c=list(sheets('kyosei_24-00-22.xlsx'))[0][1]
result['theft_sums']={col:{'male':c[col+'72'],'female':c[col+'73'],'sum':int(c[col+'72'])+int(c[col+'73'])} for col in ['J','W','X']}
print(json.dumps(result,ensure_ascii=False,indent=2))
